import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const e="/img/math-comprehensive.svg",g=JSON.parse('{"title":"小学奥数进阶：综合练习与思维挑战","description":"融会贯通才是真正的掌握。本文精选 10 道涵盖和差倍、鸡兔同笼、周期、逻辑等多个专题的综合题，挑战你的数学思维。","frontmatter":{"title":"小学奥数进阶：综合练习与思维挑战","date":"2026-02-08T11:40:00.000Z","categories":["数学"],"tags":["小学数学","奥数","综合练习"],"description":"融会贯通才是真正的掌握。本文精选 10 道涵盖和差倍、鸡兔同笼、周期、逻辑等多个专题的综合题，挑战你的数学思维。","cover":"/img/math-comprehensive.svg","top_img":"/img/banner.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-comprehensive-exercises-1.md","filePath":"posts/primary-math-olympiad-comprehensive-exercises-1.md","lastUpdated":null}'),p={name:"posts/primary-math-olympiad-comprehensive-exercises-1.md"};function l(o,a,r,i,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="小学奥数进阶-综合练习与思维挑战" tabindex="-1">小学奥数进阶：综合练习与思维挑战 <a class="header-anchor" href="#小学奥数进阶-综合练习与思维挑战" aria-label="Permalink to &quot;小学奥数进阶：综合练习与思维挑战&quot;">​</a></h1><h2 id="一、-思维导图-解题地图" tabindex="-1">一、 思维导图：解题地图 <a class="header-anchor" href="#一、-思维导图-解题地图" aria-label="Permalink to &quot;一、 思维导图：解题地图&quot;">​</a></h2><p>在面对综合题时，第一步是识别它是哪种模型。</p><p><img src="'+e+'" alt="奥数思维地图"></p><hr><h2 id="二、-精选挑战题-附简析" tabindex="-1">二、 精选挑战题（附简析） <a class="header-anchor" href="#二、-精选挑战题-附简析" aria-label="Permalink to &quot;二、 精选挑战题（附简析）&quot;">​</a></h2><h3 id="_1-组合模型-年龄-差倍" tabindex="-1">1. 组合模型：年龄 + 差倍 <a class="header-anchor" href="#_1-组合模型-年龄-差倍" aria-label="Permalink to &quot;1. 组合模型：年龄 + 差倍&quot;">​</a></h3><p><strong>题目</strong>：今年爸爸的年龄是儿子的 4 倍，3 年前爸爸和儿子的年龄和是 39 岁。求父子今年各几岁？</p><ul><li><strong>简析</strong>： <ul><li>3 年前和是 39，现在和是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>9</mn><mo>+</mo><mn>3</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>4</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">39 + 3 \\times 2 = 45</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span></span></span></span>。</li><li>转化成“和倍问题”：和 = 45，倍数 = 4。</li><li>儿子 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>4</mn><mn>5</mn><mo>÷</mo><mo>(</mo><mn>4</mn><mo>+</mo><mn>1</mn><mo>)</mo><mo>=</mo><mn>9</mn></mrow><annotation encoding="application/x-tex">= 45 \\div (4 + 1) = 9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">9</span></span></span></span> 岁，爸爸 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>9</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">= 9 \\times 4 = 36</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span> 岁。</li></ul></li></ul><h3 id="_2-逆向模型-还原-盈亏" tabindex="-1">2. 逆向模型：还原 + 盈亏 <a class="header-anchor" href="#_2-逆向模型-还原-盈亏" aria-label="Permalink to &quot;2. 逆向模型：还原 + 盈亏&quot;">​</a></h3><p><strong>题目</strong>：一筐苹果，分给甲、乙、丙三个小组。甲分到一半多 2 个，乙分到剩下的一半多 2 个，最后丙分到 6 个。原来有多少个苹果？</p><ul><li><strong>简析</strong>： <ul><li>倒推：丙有 6 个 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 乙分之前有 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>6</mn><mo>+</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">(6+2) \\times 2 = 16</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span></span></span></span> 个 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>→</mo></mrow><annotation encoding="application/x-tex">\\rightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">→</span></span></span></span> 甲分之前有 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>6</mn><mo>+</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>2</mn><mo>=</mo><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">(16+2) \\times 2 = 36</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span> 个。</li></ul></li></ul><h3 id="_3-逻辑模型-排除法" tabindex="-1">3. 逻辑模型：排除法 <a class="header-anchor" href="#_3-逻辑模型-排除法" aria-label="Permalink to &quot;3. 逻辑模型：排除法&quot;">​</a></h3><p><strong>题目</strong>：A、B、C 三人比赛。A 说：我不是最后。B 说：我不是第一。C 说：我也不是最后。结果只有一个人说对了。谁是第一？</p><ul><li><strong>简析</strong>：假设 A 是第一，则 A 对、B 对（不对，B说不是第一，若是A第一，则B是对的）、C对。不符。依次假设。</li></ul><hr><h2 id="三、-解题三部曲" tabindex="-1">三、 解题三部曲 <a class="header-anchor" href="#三、-解题三部曲" aria-label="Permalink to &quot;三、 解题三部曲&quot;">​</a></h2><ol><li><strong>审题</strong>：圈出关键词（和、差、倍、每隔、多出、余下）。</li><li><strong>建模</strong>：这是鸡兔同笼？还是盈亏问题？</li><li><strong>校验</strong>：把结果代回原题，看是否逻辑自洽。</li></ol><hr><h2 id="四、-综合练习-自主挑战" tabindex="-1">四、 综合练习（自主挑战） <a class="header-anchor" href="#四、-综合练习-自主挑战" aria-label="Permalink to &quot;四、 综合练习（自主挑战）&quot;">​</a></h2><ol><li><strong>(植树+周期)</strong> 在一条长 120 米的公路两旁栽树，每隔 5 米栽一棵。如果每两棵树之间放一盆花，共需要多少盆花？</li><li><strong>(盈亏+还原)</strong> 老师给小朋友发糖。如果每人发 4 块，多 3 块；如果每人发 6 块，就少 7 块。如果老师先吃掉 5 块，再按每人 5 块发，还剩几块？</li><li><strong>(面积+逻辑)</strong> 一个大长方形被分成四个小长方形。已知其中三个的面积分别是 10, 15, 20 平方厘米。求第四个的面积可能是多少？（考虑不同排列方式）</li></ol><hr><p><em>结语：数学不是死记硬背，而是寻找规律、建立模型的过程。希望这一系列的奥数专题能帮你打开数学的新世界！</em></p>',23)])])}const u=s(p,[["render",l]]);export{g as __pageData,u as default};
